import { getServerSupabase } from "@/lib/supabase";
import { NextRequest } from "next/server";
import { requireSport, authErrorToResponse, AuthError } from "@/lib/auth";

const supabase = getServerSupabase();

/**
 * Serve production-quality lineups from pipeline_lineups.
 *
 * These are generated by the Python pipeline (04_generate_lineups.py) using:
 * - 9-signal combined projections (Karpathy-weighted blend)
 * - ILP optimizer with proper DK position constraints
 * - Confirmed starter filtering
 * - RG ceiling/floor matchup-specific variance
 * - Injury filtering
 *
 * Falls back to on-the-fly generation only if no pipeline lineups exist.
 */

interface PipelinePlayer {
  dk_name: string;
  team: string;
  position: string;
  salary: number;
  score: number;
  is_pitcher: boolean;
  projected?: number;
  ownership_est?: number;
  sim_exposure?: number;
}

interface PipelineLineup {
  id: number;
  date: string;
  lineup_num: number;
  engine: string;
  players: PipelinePlayer[];
  total_salary: number;
  projected_score: number;
  actual_score: number | null;
  csv_text: string;
  created_at: string;
}

export async function POST(request: NextRequest) {
  try {
    await requireSport('mlb');
    const body = await request.json();
    const targetDate = body.date || new Date().toISOString().split("T")[0];

    // Try to load pre-generated pipeline lineups (the real engine output)
    const { data: pipelineLineups, error: plError } = await supabase
      .from("pipeline_lineups")
      .select("*")
      .eq("date", targetDate)
      .lte("lineup_num", 10) // Cash lineups only (GPP are 101+)
      .order("created_at", { ascending: false })
      .limit(30);

    if (pipelineLineups && pipelineLineups.length > 0) {
      // Deduplicate: keep the latest batch (same created_at timestamp)
      const latestCreated = pipelineLineups[0].created_at;
      const latestBatch = pipelineLineups.filter(
        (l: PipelineLineup) => l.created_at === latestCreated
      );

      // Load ownership. Pullers now tag rows with draft_group_id, so prefer
      // the main slate's rows; fall back to legacy date-only rows if the
      // pipeline hasn't re-pulled per slate yet. Resolve "main" as the DG
      // with the most hitters on this date.
      const [salRes, ownRes] = await Promise.all([
        supabase
          .from("std_dk_salaries")
          .select("draft_group_id, position")
          .eq("date", targetDate),
        supabase
          .from("std_ownership_projections")
          .select("player_name, projected_ownership, source, draft_group_id")
          .eq("date", targetDate)
          .in("source", ["solver", "calibrated_ownership_v3",
                          "rotogrinders_blend", "rotogrinders_premium"]),
      ]);
      let mainDg: number | null = null;
      if (salRes.data) {
        const counts = new Map<number, number>();
        for (const r of salRes.data) {
          const pos = (r.position || "").toUpperCase();
          const dg = r.draft_group_id;
          if (dg != null && !["P", "SP", "RP"].includes(pos) &&
              ["C", "1B", "2B", "3B", "SS", "OF"].includes(pos)) {
            counts.set(dg, (counts.get(dg) || 0) + 1);
          }
        }
        let best = -1;
        for (const [dg, c] of counts) {
          if (c > best) { best = c; mainDg = dg; }
        }
      }
      const PRI: Record<string, number> = {
        solver: 4, calibrated_ownership_v3: 3,
        rotogrinders_blend: 2, rotogrinders_premium: 1,
      };
      const ownMap = new Map<string, number>();
      if (ownRes.data) {
        const slateRows = ownRes.data.filter(
          (r) => mainDg != null && Number(r.draft_group_id) === mainDg,
        );
        const legacyRows = ownRes.data.filter((r) => r.draft_group_id == null);
        const pool = slateRows.length ? slateRows : legacyRows;
        const byPlayer = new Map<string, { own: number; pri: number }>();
        for (const r of pool) {
          const key = (r.player_name as string || "").toLowerCase();
          const own = Number(r.projected_ownership);
          if (!key || !Number.isFinite(own) || own <= 0) continue;
          const pri = PRI[r.source as string] ?? 0;
          const prev = byPlayer.get(key);
          if (!prev || pri > prev.pri) byPlayer.set(key, { own, pri });
        }
        for (const [k, v] of byPlayer) ownMap.set(k, v.own);
      }

      const lineups = latestBatch.map((lu: PipelineLineup) => {
        const players = (lu.players || []).map((p: PipelinePlayer) => ({
          name: p.dk_name,
          position: p.position,
          salary: p.salary,
          projected: p.score,
          team: p.team,
          ownership_est: ownMap.get(p.dk_name?.toLowerCase()) ?? null,
          sim_exposure: p.sim_exposure ?? null,
        }));

        return {
          lineup_num: lu.lineup_num,
          players,
          total_salary: lu.total_salary,
          projected_score: lu.projected_score,
          actual_score: lu.actual_score,
          engine: lu.engine,
          created_at: lu.created_at,
        };
      });

      // Count projection sources
      const { count: nProjections } = await supabase
        .from("std_ev_propsheet")
        .select("*", { count: "exact", head: true })
        .eq("date", targetDate)
        .eq("site", "combined");

      const { count: nSalaries } = await supabase
        .from("std_dk_salaries")
        .select("*", { count: "exact", head: true })
        .eq("date", targetDate);

      return Response.json({
        date: targetDate,
        source: "pipeline",
        n_projections: nProjections || 0,
        n_salaries: nSalaries || 0,
        n_ownership: ownMap.size,
        lineups,
        meta: {
          engine: latestBatch[0]?.engine || "production_cash_v2",
          generated_at: latestCreated,
          n_projections: nProjections || 0,
          projection_source: "9-signal combined (BAT X via RotoGrinders + market consensus)",
        },
      });
    }

    // No pipeline lineups — tell user to run the pipeline
    return Response.json({
      date: targetDate,
      source: "none",
      error: "No pipeline lineups for this date. Run the pipeline first, or use /api/generate with the ILP optimizer.",
      lineups: [],
    });
  } catch (err) {
    if (err instanceof AuthError) return authErrorToResponse(err);
    return Response.json({ error: String(err), lineups: [] }, { status: 500 });
  }
}

// Greedy builder removed. All lineup generation now uses ILP (via /api/generate)
// or serves pre-computed pipeline lineups from pipeline_lineups table.
